mapper.select:
select device_ip as ip
from t800_uv_inexus.t_ins_info_temp
where device_serial_number = #{device_serial_number}

select b.attachment_name
from t800_uv_inexus.t_ins_info_temp a inner join t800_uv_inexus.t_measure_pool b on a.attachment_type = b.attachment_num
where a.device_serial_number = #{device_serial_number}
